CREATE TABLE IF NOT EXISTS audit_trails (id uuid PRIMARY KEY, bron VARCHAR(50) NOT NULL, applicatie_id VARCHAR(100) NULL, applicatie_weergave VARCHAR(200) NULL, gebruikers_id VARCHAR(255) NULL, gebruikers_weergave VARCHAR(255) NULL, actie VARCHAR(50) NOT NULL, actie_weergave VARCHAR(200) NULL, resultaat INT NULL, hoofd_object VARCHAR(1000) NOT NULL, resource VARCHAR(50) NOT NULL, resource_url VARCHAR(1000) NOT NULL, toelichting TEXT NULL, resource_weergave VARCHAR(200) NULL, aanmaakdatum TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, wijzigingen TEXT DEFAULT '{}' NOT NULL);
ALTER TABLE eio_versions ALTER COLUMN trefwoorden TYPE VARCHAR(100)[], ALTER COLUMN trefwoorden SET DEFAULT ARRAY[]::varchar[];
